  "townTrusts: tupaq sees you as more respectful than extractive # the town trusts you",
  "rosaHurt: rosa knows take, khipu # Mama Rosa saw",
  "arceKnowsLie: arce knows lie, arce # Arce knows you lied",
  "hasCopies: player with copy >= 1 # your copies",
  "haveContract: photographed_books == true or given_contract == true or have_file == true or arce knows smuggle, arce # the contract",
  "",
